/**
 * Entry file generator — produces a minimal src/generated/app.ts
 *
 * All server orchestration (middleware, health routes, analytics, workbench,
 * static serving, Bun.serve) lives in @agentuity/runtime's bootstrap().
 * The generated file just wires imports and calls bootstrap().
 */

import { join } from 'node:path';
import type { Logger, WorkbenchConfig, AnalyticsConfig } from '../../types';

interface GenerateEntryOptions {
	rootDir: string;
	projectId: string;
	deploymentId: string;
	logger: Logger;
	mode: 'dev' | 'prod';
	// Retained for caller compatibility — bootstrap reads these from createApp() config
	workbench?: WorkbenchConfig;
	analytics?: boolean | AnalyticsConfig;
	noBundle?: boolean;
}

/**
 * Generate a minimal entry file that delegates to runtime bootstrap.
 */
export async function generateEntryFile(options: GenerateEntryOptions): Promise<void> {
	const { rootDir, logger } = options;

	const generatedDir = join(rootDir, 'src', 'generated');
	const entryPath = join(generatedDir, 'app.ts');

	logger.trace('Generating entry file...');

	const code = `// @generated
// Auto-generated by Agentuity — DO NOT EDIT
// All server logic lives in @agentuity/runtime bootstrap()
import { createRouter, setGlobalRouter } from '@agentuity/runtime';

// Step 1: Create router before app.ts so users can add middleware
// (e.g., app.router.use('/api/*', authMiddleware()))
const app = createRouter();
setGlobalRouter(app);

// Step 2: Import agent registry (registers all agents)
import './registry.js';

// Step 3: Import user's app.ts (runs createApp(), stores config/state)
import '../../app.js';

// Step 4: Bootstrap server (middleware, routes, Bun.serve)
import { bootstrap } from '@agentuity/runtime';
await bootstrap();
`;

	await Bun.write(entryPath, code);
	logger.trace('Generated entry file at %s', entryPath);
}
